import * as React from 'react'
import { Tooltip } from 'antd'
import DeviceHubIcon from '@material-ui/icons/DeviceHub'
import InfoIcon from '@material-ui/icons/Info'
import TimelineIcon from '@material-ui/icons/Timeline'
import SettingsInputComponentIcon from '@material-ui/icons/SettingsInputComponent'
import { withStyles } from '@material-ui/core/styles'

import { Node } from '../Topology'
import { styles } from './HostDetailPanelStyles'
import { DetailBadge, DetailBadgeTone, DetailEmpty, DetailKeyValueList, DetailSection } from './common'

interface Props {
    classes: any
    node: Node
    moldInventory?: any
    vmNameMap?: Record<string, string>
    vmNetworkMap?: Record<string, Array<VMNetworkMapItem>>
    vmDetailMap?: Record<string, any>
}

interface State {
    collapsed: Record<string, boolean>
}

interface KeyValueRow {
    label: string
    value: any
    variant?: 'networkType' | 'state'
}

interface FeatureItem {
    name: string
    enabled: boolean
}

interface VMNetworkMapItem {
    networkName: string
    macAddress: string
    ipAddress: string
    networkType?: string
    trafficType?: string
    gateway?: string
    cidr?: string
    broadcastUri?: string
    isDefault?: string
    networkOffering?: string
}

interface MatchedVMNetwork {
    vmKey: string
    vmName: string
    networkName: string
    macAddress: string
    ipAddress: string
    networkType?: string
    trafficType?: string
    gateway?: string
    cidr?: string
    broadcastUri?: string
    isDefault?: string
    networkOffering?: string
}

const isBlank = (value: any): boolean => {
    if (value === undefined || value === null) return true
    if (Array.isArray(value)) return value.length === 0
    if (typeof value === 'string') return value.trim() === ''
    return false
}

const asArray = (value: any): any[] => {
    if (isBlank(value)) return []
    return Array.isArray(value) ? value : [value]
}

const stringify = (value: any): string => {
    if (isBlank(value)) return ''
    if (Array.isArray(value)) return value.map(item => stringify(item)).filter(Boolean).join(', ')
    if (typeof value === 'object') {
        try {
            return JSON.stringify(value)
        } catch (e) {
            return String(value)
        }
    }
    return String(value)
}

const valueByPath = (data: any, path: string): any => {
    if (!path || path.indexOf('.') < 0) return data?.[path]
    return path.split('.').reduce((current, key) => current?.[key], data)
}

const firstValue = (data: any, keys: string[]): string => {
    for (const key of keys) {
        const value = stringify(valueByPath(data, key))
        if (value) return value
    }
    return ''
}

const firstRaw = (data: any, keys: string[]): any => {
    for (const key of keys) {
        const value = valueByPath(data, key)
        if (!isBlank(value)) return value
    }
    return undefined
}

const normalizeText = (value: string): string => String(value || '').trim()

const formatDate = (value: any): string => {
    if (isBlank(value)) return ''
    const numeric = Number(value)
    const date = !Number.isNaN(numeric) && String(value).length <= 10
        ? new Date(numeric * 1000)
        : new Date(value)
    if (Number.isNaN(date.getTime())) return stringify(value)
    return date.toLocaleString()
}

const formatBytes = (value: any): string => {
    if (isBlank(value)) return ''
    const bytes = Number(value)
    if (Number.isNaN(bytes)) return stringify(value)
    const units = ['bytes', 'KB', 'MB', 'GB', 'TB']
    let size = bytes
    let unitIndex = 0
    while (size >= 1024 && unitIndex < units.length - 1) {
        size = size / 1024
        unitIndex += 1
    }
    const display = unitIndex === 0 ? String(Math.round(size)) : size.toFixed(size >= 10 ? 1 : 2).replace(/\.0$/, '')
    return `${display} ${units[unitIndex]} (${bytes.toLocaleString()} bytes)`
}

class VMNetworkDetailPanel extends React.Component<Props, State> {
    state: State = {
        collapsed: {
            features: true,
            advanced: true,
            raw: true
        }
    }

    private data(): any {
        return this.props.node.data || {}
    }

    private toggleSection(key: string) {
        this.setState({
            collapsed: {
                ...this.state.collapsed,
                [key]: !this.state.collapsed[key]
            }
        })
    }

    private name(): string {
        const data = this.data()
        return firstValue(data, ['Name', 'name', 'InterfaceName', 'IfName', 'IfAlias', 'Device', 'ID', 'id']) || this.props.node.id
    }

    private interfaceType(): string {
        const data = this.data()
        const explicit = firstValue(data, ['InterfaceType', 'IfaceType', 'IfType', 'Kind', 'LinkType', 'TunType', 'TUNType'])
        if (explicit) return explicit
        const driver = firstValue(data, ['Driver', 'driver'])
        const name = this.name().toLowerCase()
        if (/vnet|tap|tun/.test(name) || /tap|tun/.test(driver.toLowerCase())) return 'tuntap'
        return firstValue(data, ['Type', 'type'])
    }

    private networkType(): string {
        const data = this.data()
        const value = firstValue(data, [
            'MoldNetworkType',
            'NetworkType',
            'networkType',
            'TrafficType',
            'GuestType',
            'guestType',
            'TypeDetail',
            'Mold.NetworkType'
        ])
        const normalized = value.toLowerCase()
        if (normalized === 'l2' || normalized.indexOf('l2') >= 0) return 'L2'
        if (normalized.indexOf('isolated') >= 0) return 'Isolated'
        if (normalized.indexOf('shared') >= 0) return 'Shared'
        return value
    }

    private networkTypeDescription(type = this.networkType()): string {
        switch (type.toLowerCase()) {
            case 'l2':
                return '동일 L2 네트워크에 직접 연결된 네트워크입니다.'
            case 'isolated':
                return '격리 네트워크이며 Virtual Router를 통해 외부 통신할 수 있습니다.'
            case 'shared':
                return '여러 VM이 공유하는 네트워크입니다.'
            default:
                return ''
        }
    }

    private stateText(): string {
        return firstValue(this.data(), ['State', 'state', 'Status', 'status', 'OperState', 'operstate', 'LinkState'])
    }

    private mac(): string {
        return firstValue(this.data(), ['MAC', 'Mac', 'MacAddress', 'macAddress', 'HardwareAddr', 'LLAddr'])
    }

    private ipAddress(): string {
        return firstValue(this.data(), ['IpAddress', 'ipAddress', 'ipaddress', 'IP', 'IPv4', 'IPV4']) || this.ipv4Addresses()[0] || this.ipv6Addresses()[0]
    }

    private matchedVMNetwork(): MatchedVMNetwork | undefined {
        const mac = this.mac().toLowerCase()
        const ip = this.ipAddress()
        const vmNetworkMap = this.props.vmNetworkMap || {}
        for (const vmKey of Object.keys(vmNetworkMap)) {
            for (const network of vmNetworkMap[vmKey] || []) {
                const networkMac = String(network.macAddress || '').toLowerCase()
                const networkIp = String(network.ipAddress || '')
                if ((mac && networkMac && mac === networkMac) || (ip && networkIp && ip === networkIp)) {
                    return {
                        vmKey,
                        vmName: this.props.vmNameMap?.[vmKey] || vmKey,
                        networkName: network.networkName || '',
                        macAddress: network.macAddress || '',
                        ipAddress: network.ipAddress || '',
                        networkType: network.networkType || '',
                        trafficType: network.trafficType || '',
                        gateway: network.gateway || '',
                        cidr: network.cidr || '',
                        broadcastUri: network.broadcastUri || '',
                        isDefault: network.isDefault || '',
                        networkOffering: network.networkOffering || ''
                    }
                }
            }
        }
        return undefined
    }

    private ipv4Addresses(): string[] {
        const data = this.data()
        return [
            ...asArray(data.IPV4),
            ...asArray(data.IPv4),
            ...asArray(data.ipv4),
            ...asArray(data.IP),
            ...asArray(data.Addr),
            ...asArray(data.IpAddress),
            ...asArray(data.ipaddress)
        ].map(stringify).filter(value => value && value.indexOf(':') < 0)
    }

    private ipv6Addresses(): string[] {
        const data = this.data()
        return [
            ...asArray(data.IPV6),
            ...asArray(data.IPv6),
            ...asArray(data.ipv6),
            ...asArray(data.Addr),
            ...asArray(data.IpAddress)
        ].map(stringify).filter(value => value && value.indexOf(':') >= 0)
    }

    private badgeTone(kind: 'networkType' | 'state', value: string): DetailBadgeTone {
        const normalized = String(value || '').toLowerCase()
        if (kind === 'networkType') {
            if (normalized === 'l2' || normalized === 'isolated') return 'info'
            if (normalized === 'shared') return 'success'
            return 'default'
        }
        if (normalized === 'up' || normalized === 'running') return 'success'
        if (normalized === 'down' || normalized === 'failed') return 'danger'
        if (normalized === 'unknown') return 'warning'
        return 'default'
    }

    private renderValue(row: KeyValueRow) {
        const value = stringify(row.value) || '-'
        if (row.variant === 'networkType') {
            const description = this.networkTypeDescription(value)
            const badge = <DetailBadge tone={this.badgeTone(row.variant, value)}>{value}</DetailBadge>
            return description ? <Tooltip title={description} placement="top">{badge}</Tooltip> : badge
        }
        if (row.variant === 'state') {
            return <DetailBadge tone={this.badgeTone(row.variant, value)}>{value}</DetailBadge>
        }
        return value
    }

    private renderRows(rows: KeyValueRow[], emptyText = '-', showBlankRows = false) {
        const visible = showBlankRows ? rows : rows.filter(row => !isBlank(row.value))
        if (!visible.length) return <DetailEmpty description={emptyText} compact />
        return (
            <DetailKeyValueList rows={visible.map(row => ({
                key: row.label,
                label: row.label,
                value: this.renderValue(row),
                textValue: stringify(row.value) || '-'
            }))} />
        )
    }

    private renderSection(key: string, icon: React.ReactNode, title: string, _description: string, children: React.ReactNode, defaultCollapsed = false) {
        const collapsed = this.state.collapsed[key] !== undefined ? this.state.collapsed[key] : defaultCollapsed
        return (
            <DetailSection
                icon={icon}
                title={title}
                collapsible
                collapsed={collapsed}
                onToggle={() => this.toggleSection(key)}>
                {children}
            </DetailSection>
        )
    }

    private networkName(): string {
        const matched = this.matchedVMNetwork()
        return matched?.networkName || firstValue(this.data(), ['MoldNetworkName', 'NetworkName', 'networkName', 'Network', 'network'])
    }

    private moldNetworkType(): string {
        return this.matchedVMNetwork()?.networkType || this.networkType()
    }

    private primaryNic(): string {
        return this.matchedVMNetwork()?.isDefault || firstValue(this.data(), ['IsDefault', 'isDefault', 'Primary', 'primary', 'DefaultNic', 'defaultNic'])
    }

    private bridgeOrBusInfo(): string {
        const data = this.data()
        return firstValue(data, ['Bridge', 'BridgeName', 'bridge', 'Master', 'MasterName', 'BusInfo', 'busInfo', 'Bus', 'bus'])
    }

    private basicRows(): KeyValueRow[] {
        const data = this.data()
        const matched = this.matchedVMNetwork()
        return [
            { label: '이름', value: this.name() },
            { label: '상태', value: this.stateText(), variant: 'state' },
            { label: '네트워크 유형', value: this.moldNetworkType(), variant: 'networkType' },
            { label: '네트워크 이름', value: this.networkName() },
            { label: 'IP 주소', value: matched?.ipAddress || this.ipAddress() },
            { label: 'MAC 주소', value: matched?.macAddress || this.mac() },
            { label: 'Primary NIC 여부', value: this.primaryNic() },
            { label: 'Gateway', value: matched?.gateway || firstValue(data, ['Gateway', 'gateway']) },
            { label: '인터페이스 이름', value: firstValue(data, ['IfName', 'InterfaceName', 'Name', 'name']) },
            { label: '드라이버', value: firstValue(data, ['Driver', 'driver']) },
            { label: '브리지 또는 버스 정보', value: this.bridgeOrBusInfo() },
            { label: 'MTU', value: firstValue(data, ['MTU', 'Mtu', 'mtu']) }
        ]
    }

    private libvirtRows(): KeyValueRow[] {
        const data = this.data()
        const libvirt = firstRaw(data, ['Libvirt', 'libvirt', 'Metadata', 'metadata']) || {}
        const source = typeof libvirt === 'object' ? { ...data, ...libvirt } : data
        return [
            { label: 'Alias', value: firstValue(source, ['Alias', 'alias']) },
            { label: 'BusInfo', value: firstValue(source, ['BusInfo', 'busInfo']) },
            { label: 'BusType', value: firstValue(source, ['BusType', 'busType']) },
            { label: 'Domain', value: firstValue(source, ['Domain', 'domain']) },
            { label: 'MAC', value: firstValue(source, ['MAC', 'Mac', 'MACAddress', 'macAddress']) }
        ]
    }

    private linkFlags(): string[] {
        const data = this.data()
        const flags = firstRaw(data, ['Flags', 'flags', 'LinkFlags', 'linkFlags'])
        if (Array.isArray(flags)) return flags.map(stringify).filter(Boolean)
        const flagText = stringify(flags)
        if (flagText) return flagText.split(/[,\s|]+/).map(normalizeText).filter(Boolean)
        const state = this.stateText()
        return state ? [state] : []
    }

    private renderConnectionInfo() {
        const flags = this.linkFlags()
        return this.renderRows([
            ...this.libvirtRows(),
            { label: '링크 플래그', value: flags.join(', ') }
        ])
    }

    private renderAddressInfo() {
        const ipv4 = this.ipv4Addresses()
        const ipv6 = this.ipv6Addresses()
        if (!ipv4.length && !ipv6.length) return <DetailEmpty description="주소 정보 없음" compact />
        return this.renderRows([
            { label: 'IPv4', value: ipv4.join(', ') },
            { label: 'IPv6', value: ipv6.join(', ') }
        ])
    }

    private metricData(field: 'LastUpdateMetric' | 'Metric'): any {
        return firstRaw(this.data(), [field, `Ovs.${field}`])
    }

    private hasTrafficMetric(metric: any): boolean {
        if (!metric || typeof metric !== 'object') return false
        return ['RxPackets', 'RxBytes', 'TxPackets', 'TxBytes'].some(key => metric[key] !== undefined && metric[key] !== null)
    }

    private metricRows(metric: any, recent: boolean): KeyValueRow[] {
        if (!this.hasTrafficMetric(metric)) return []
        const rows: Array<{ key: string, label: string, format: (value: any) => string }> = [
            { key: 'RxPackets', label: '수신 패킷 수', format: value => Number(value).toLocaleString() },
            { key: 'RxBytes', label: '수신 바이트 수', format: formatBytes },
            { key: 'TxPackets', label: '송신 패킷 수', format: value => Number(value).toLocaleString() },
            { key: 'TxBytes', label: '송신 바이트 수', format: formatBytes }
        ]
        if (recent) rows.push({ key: 'Start', label: '수집 시작 시간', format: formatDate })
        rows.push({ key: 'Last', label: '최종 수집 시간', format: formatDate })
        return rows
            .filter(row => metric[row.key] !== undefined && metric[row.key] !== null)
            .map(row => ({ label: row.label, value: row.format(metric[row.key]) }))
    }

    private featureItems(): FeatureItem[] {
        const features = firstRaw(this.data(), ['Features', 'features', 'Offload', 'offload', 'Offloads', 'offloads'])
        if (!features || typeof features !== 'object') return []
        return Object.keys(features)
            .map(key => ({ name: key, enabled: features[key] === true || String(features[key]).toLowerCase() === 'true' }))
            .sort((a, b) => Number(b.enabled) - Number(a.enabled) || a.name.localeCompare(b.name))
    }

    private renderFeatures() {
        const { classes } = this.props
        const items = this.featureItems()
        if (!items.length) return <DetailEmpty description="장비 기능 정보 없음" compact />
        return (
            <div className={classes.featureTable}>
                {items.map(item => (
                    <div className={classes.featureRow} key={item.name}>
                        <span className={classes.featureName}>{item.name}</span>
                        <DetailBadge tone={item.enabled ? 'success' : 'default'}>{item.enabled ? 'true' : 'false'}</DetailBadge>
                    </div>
                ))}
            </div>
        )
    }

    private advancedInfo(): Record<string, any> {
        const data = this.data()
        const advanced: Record<string, any> = {}
        ;[
            ['포워딩 데이터베이스(FDB)', ['FDB', 'Fdb', 'fdb', 'ForwardingDatabase']],
            ['인접 장비 정보', ['Neighbors', 'neighbours', 'Neighbor', 'LLDP']],
            ['라우팅 테이블', ['RoutingTable', 'Routes', 'routes', 'Route']],
            ['Libvirt Metadata', ['Libvirt', 'libvirt', 'Metadata', 'metadata']],
            ['기타 raw 데이터', ['Raw', 'raw']]
        ].forEach(([label, keys]) => {
            const value = firstRaw(data, keys as string[])
            if (!isBlank(value)) advanced[label as string] = value
        })
        return advanced
    }

    private renderAdvanced() {
        const advanced = this.advancedInfo()
        if (!Object.keys(advanced).length) return <DetailEmpty description="고급 정보 없음" compact />
        return <pre className={this.props.classes.jsonBox}>{JSON.stringify(advanced, null, 2)}</pre>
    }

    render() {
        const { classes } = this.props
        const recentMetricRows = this.metricRows(this.metricData('LastUpdateMetric'), true)
        const accumulatedMetricRows = this.metricRows(this.metricData('Metric'), false)
        const hasConnectionInfo = this.libvirtRows().some(row => !isBlank(row.value)) || this.linkFlags().length > 0
        const hasAddresses = this.ipv4Addresses().length > 0 || this.ipv6Addresses().length > 0
        const hasFeatures = this.featureItems().length > 0
        const hasAdvanced = Object.keys(this.advancedInfo()).length > 0
        return (
            <div className={classes.root}>
                {this.renderSection('basic', <InfoIcon />, '기본 정보', '인터페이스 식별 정보와 장치 속성입니다.', this.renderRows(this.basicRows()))}
                {hasConnectionInfo && this.renderSection('connection', <DeviceHubIcon />, '연결 정보', 'Libvirt 메타데이터와 링크 플래그입니다.', this.renderConnectionInfo())}
                {hasAddresses && this.renderSection('addresses', <SettingsInputComponentIcon />, '주소 정보', 'IPv4 / IPv6 주소를 분리해 표시합니다.', this.renderAddressInfo())}
                {recentMetricRows.length > 0 && this.renderSection('recent', <TimelineIcon />, '최근 수집 지표', '최근 수집된 트래픽 지표입니다.', <DetailKeyValueList rows={recentMetricRows} />)}
                {accumulatedMetricRows.length > 0 && this.renderSection('accumulated', <TimelineIcon />, '누적 수집 지표', '누적 트래픽 카운터입니다.', <DetailKeyValueList rows={accumulatedMetricRows} />)}
                {hasFeatures && this.renderSection('features', <SettingsInputComponentIcon />, '장비 기능', 'Offload 기능 목록입니다. true 항목을 먼저 표시합니다.', this.renderFeatures(), true)}
                {hasAdvanced && this.renderSection('advanced', <InfoIcon />, '고급 정보', 'FDB, 인접 장비, 라우팅 테이블과 raw 데이터입니다.', this.renderAdvanced(), true)}
            </div>
        )
    }
}

export default withStyles(styles)(VMNetworkDetailPanel)
